import{z as B,x as d,o as i,c as p,q as s,j as l,D as n,d as e,s as o,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"数学归纳","description":"","frontmatter":{"title":"数学归纳","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mathematical-induction.md","filePath":"cs/mathematical-induction.md","lastUpdated":1791063341000}'),A={name:"cs/mathematical-induction.md"};function m(c,a,h,P,k,u){const r=d("Mermaid");return i(),p("div",null,[a[2]||(a[2]=s('<h1 id="数学归纳" tabindex="-1">数学归纳 <a class="header-anchor" href="#数学归纳" aria-label="Permalink to &quot;数学归纳&quot;">​</a></h1><div class="epigraph"><p>要证明每个自然数都有某性质，只需验证 $0$，再证明「若 $n$ 有则 $n+1$ 有」。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/functions-countable">函数与可数</a>钉死了 \\(\\mathbb{N}\\) 可作编号。本课不重证可数，也不从「公理化算术」另起。缺口是：可数只说有一份清单，没有工具证明「清单上每一个都满足 \\(P\\)」。后课循环不变式、递归结构、树的性质，都要把 \\(P\\) 沿 \\(\\mathbb{N}\\) 推过去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对有限 \\(n=5\\) 可以穷举。对所有 \\(n\\)，穷举不是证明。缺口因此不是新的集合，而是归纳法则：若 \\(P(0)\\)，且 \\(\\forall k\\,(P(k)\\Rightarrow P(k+1))\\)，则 \\(\\forall n\\,P(n)\\)。强归纳把假设加强成「小于 \\(n\\) 的都真」；对递归定义的结构（树、公式），换成结构归纳：对子对象成立则对对象成立。</p><p><span class="marginnote">术语翻译：强归纳的「强」指假设变多——不只假设第 \\(k\\) 步成立，而是假设 \\(0\\) 到 \\(k\\) 每一步都成立。比如证「每个大于 1 的整数可写成质因数之积」，要对 \\(k+1\\) 的某个真因子调用归纳假设，弱归纳那一条假设不够用，结论强度其实与弱归纳相同。</span></p><p>本课只钉这套格式。渐近记号是下一课：归纳证明正确，不自动给出 \\(O(n^2)\\)。</p><h3 id="归纳假设不是「想当然成立」" tabindex="-1">归纳假设不是「想当然成立」 <a class="header-anchor" href="#归纳假设不是「想当然成立」" aria-label="Permalink to &quot;归纳假设不是「想当然成立」&quot;">​</a></h3><p>必须写清 \\(P(k)\\) 的语句，再在 \\(k+1\\) 的论证里<strong>调用</strong>它。只检查前几项再写「依此类推」，不是归纳。基础步选错（从 \\(1\\) 起却漏了 \\(0\\)，或树归纳漏了空树）会整棵倒掉。</p><p><span class="marginnote">Rosen 把归纳与递归定义对照：自然数、阶乘、树高。后课<a href="/cs/loop-invariant">循环不变式</a>把同一法则用在循环轮次上；本课先在 \\(\\mathbb{N}\\) 上钉格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(P(n)\\)；证 \\(P(0)\\)；假设 \\(P(k)\\) 证 \\(P(k+1)\\)。对象若按大小递归定义，对定义的每条规则给一步。常见错误：在 \\(k+1\\) 步用了 \\(P(k+1)\\) 自身。</p><p><span class="marginnote">直觉类比：归纳像推多米诺骨牌——基础步是用手推倒第一张，归纳步是保证每张倒下时必撞倒下一张。两个条件都成立，整排必倒；只亲眼确认前几张会倒，对整排什么也没有证明。</span></p>',13)),(i(),l(E,null,{default:n(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22P(0)%22%5D%20--%3E%20STEP%5B%22P(k)%20%E2%87%92%20P(k%2B1)%22%5D%0A%20%20STEP%20--%3E%20ALL%5B%22%E2%88%80n%20P(n)%22%5D%0A%20%20ALL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%B8%90%E8%BF%91%E4%B8%8E%E5%9B%BE%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("递归函数的终止与正确性用归纳：参数变小的调用对应更小的 \\(n\\)。后课图若无环，可以沿拓扑序归纳；有环则这条路断——那是"),t("a",{href:"/cs/tree-as-acyclic"},"树作为无环连通图"),e("才强调的。本课不把图请进来，只把 \\(\\mathbb{N}\\) 上的梯子搭好。")],-1)),a[5]||(a[5]=t("p",null,"一步归纳里到底允许借用什么、不许借用什么，三种格式各有一条纪律：",-1)),(i(),l(E,null,{default:n(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ONE%5B%22%E8%A6%81%E8%AF%81%E7%9A%84%E4%B8%80%E6%AD%A5%EF%BC%9AP(k%2B1)%22%5D%20--%3E%20Q%5B%22%E5%85%81%E8%AE%B8%E8%B0%83%E7%94%A8%E5%93%AA%E4%BA%9B%E5%81%87%E8%AE%BE%22%5D%0A%20%20Q%20--%3E%20W%5B%22%E5%BC%B1%E5%BD%92%E7%BA%B3%EF%BC%9A%E5%8F%AA%E6%9C%89%20P(k)%22%5D%0A%20%20Q%20--%3E%20S%5B%22%E5%BC%BA%E5%BD%92%E7%BA%B3%EF%BC%9AP(0)%20%E5%88%B0%20P(k)%20%E5%85%A8%E9%83%A8%22%5D%0A%20%20Q%20--%3E%20T%5B%22%E7%BB%93%E6%9E%84%E5%BD%92%E7%BA%B3%EF%BC%9A%E5%90%84%E7%9C%9F%E5%AD%90%E7%BB%93%E6%9E%84%E7%9A%84%20P%22%5D%0A%20%20W%20--%3E%20NO%5B%22%E9%83%BD%E4%B8%8D%E8%AE%B8%E8%B0%83%E7%94%A8%20P(k%2B1)%20%E8%87%AA%E8%BA%AB%22%5D%0A%20%20S%20--%3E%20NO%0A%20%20T%20--%3E%20NO%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：写「由 \\(P(k+1)\\) 可知 \\(P(k+1)\\)」是把要证的结论当前提，属循环论证。归纳假设只允许更小的对象；把「我调用的是哪条假设」写成显式的一句，是归纳证明格式的硬要求，漏掉常常是出错的起点。</span></p><p>归纳也能证不等式，给下一课 \\(\\Theta\\) 的具体函数比较当工具，但 \\(O\\)、\\(o\\) 的定义本身不是归纳。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入超限归纳、序数。也不把数学归纳法与「实验归纳」混名。Peano 公理的其他条（后继单射等）不展开。</p><p>后课默认：对全体自然数或全体有限树的命题，用归纳写；循环的轮次归纳是同一法则的实例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归纳 = 基础 + 前一步推出后一步（或全体更小）。</li><li>递归定义的对象用结构归纳。</li><li>正确性归纳不代替代价分析；渐近是下一课。</li><li>出处：Rosen, <em>Discrete Mathematics</em>。</li></ul>',7))])}const D=B(A,[["render",m]]);export{b as __pageData,D as default};
